import { FC, useCallback } from 'react';

import { withRouter } from 'next/router';

import { createContextMenuChannel } from '@common/utils/enterprise-channels';
import { PopupWindowMenuType } from '@common/utils/popup-window';
import { Router } from '@common/utils/router';
import { WindowName } from '@common/utils/window';

import ContextMenu from '@enterprise/components/App/ContextMenu/ContextMenu';
import RenameSupertabInput from '@enterprise/components/App/ContextMenu/RenameSupertabInput';
import BrowserThemeProvider from '@enterprise/components/App/ThemeProvider/BrowserThemeProvider';

import { useIsWindows } from '@enterprise/hooks/useIsWindows';
import { ContextMenuWindowMessage, useManagePopupWindow } from '@enterprise/hooks/useManagePopupWindow';

interface Props {
    router: Router;
}

export const ContextMenuPopup: FC<Props> = ({ router: _router }) => {
    const isWindows = useIsWindows();

    const { payload, showPopup, onResponse } = useManagePopupWindow<ContextMenuWindowMessage>(
        WindowName.EnterpriseContextMenu,
        createContextMenuChannel,
        undefined,
        { blurBehavior: 'hide' }
    );

    const onComponentResponse = useCallback(
        (data?: any) => {
            onResponse(data);
            if (payload?.parentIdentity) {
                // This is an existing race condition when clicking new tab/window in the context menu
                // TODO: WRK-5551 - refactor modal events to carry focus target and centralize focus restoration in a coordinator
                fin.Window.wrapSync(payload.parentIdentity).focus();
            }
        },
        [onResponse, payload?.parentIdentity]
    );

    const renderContent = () => {
        switch (payload?.type) {
            case PopupWindowMenuType.GlobalMenu:
            case PopupWindowMenuType.ContextMenu:
                return (
                    <ContextMenu
                        messageData={payload}
                        onResponse={onComponentResponse}
                        showPopup={showPopup}
                        isWindows={isWindows}
                    />
                );
            case PopupWindowMenuType.RenameSupertab:
                return (
                    <RenameSupertabInput
                        messageData={payload}
                        onResponse={onComponentResponse}
                        showPopup={showPopup}
                        isWindows={isWindows}
                    />
                );
            default:
                return <></>;
        }
    };

    return <BrowserThemeProvider>{renderContent()}</BrowserThemeProvider>;
};

export default withRouter(ContextMenuPopup);
